"""Patch the validated Cloudflare release with the Career Pro V1 billing UI.

The presentation intentionally follows the polished Career Pro modal/card from
EggyPDF's earlier release package, while all account, checkout, creator-code and
entitlement calls use the current Supabase + Dodo V1 backend.
"""
from pathlib import Path
import re

STYLE = r'''<style id="careerBillingStyle">
.billing-modal{position:fixed;inset:0;background:rgba(17,24,39,.58);z-index:10050;display:none;align-items:center;justify-content:center;padding:18px}.billing-modal.open,.billing-modal.show{display:flex}.billing-box{width:min(720px,100%);max-height:92vh;overflow:auto;background:#fff;border:1px solid #ead7ac;border-radius:22px;box-shadow:0 28px 80px rgba(15,23,42,.22);position:relative;padding:28px}.billing-close{position:absolute;right:16px;top:14px;width:36px;height:36px;border:1px solid #e5e7eb;border-radius:50%;background:#fff;font-size:22px;cursor:pointer;color:#374151}.billing-head{text-align:center;padding:4px 32px 18px}.billing-crown{width:34px;height:34px;fill:#f5a623;margin-bottom:6px}.billing-head h2{font-size:30px;line-height:1.1;color:#1a1a2e;margin:0 0 7px}.billing-head p{color:#6b7280;font-size:13px}.billing-tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:5px;background:#f3f4f6;border-radius:999px;margin:2px auto 22px;max-width:440px}.billing-plan{border:0;background:transparent;border-radius:999px;padding:11px 12px;font-weight:800;cursor:pointer;color:#4b5563;position:relative;text-align:center}.billing-plan.active{background:#fff;color:#1a1a2e;box-shadow:0 2px 8px rgba(0,0,0,.08)}.billing-plan b{font-size:14px}.billing-save-tag{position:absolute;right:-4px;top:-22px;background:#dcfce7;color:#166534;border:1px solid #bbf7d0;border-radius:999px;padding:3px 7px;font-size:10px;font-weight:800}.billing-plan-main{background:linear-gradient(135deg,#fff8ed,#fff);border:1px solid #f5c45b;border-radius:18px;padding:22px}.billing-price{text-align:center}.billing-price strong{font-size:38px;font-weight:900;color:#1a1a2e;letter-spacing:-1px}.billing-price .period{font-size:13px;color:#6b7280}.billing-price p{font-size:13px;color:#4b5563;margin-top:2px}.billing-save{display:inline-block;margin-top:8px;background:#ecfdf5;color:#166534;border:1px solid #bbf7d0;border-radius:999px;padding:5px 10px;font-size:11px;font-weight:800}.billing-credits{margin:19px 0 14px;padding:13px 14px;border-radius:12px;background:#fff;border:1px solid #f1d89f;display:flex;align-items:center;justify-content:space-between;gap:12px}.billing-credits b{font-size:16px}.billing-credits span{font-size:11px;color:#6b7280}.billing-features{display:grid;grid-template-columns:1fr 1fr;gap:9px 16px;margin:16px 0}.billing-features div{font-size:12px;color:#374151}.billing-features strong{color:#1a1a2e}.billing-features span{color:#16a34a;font-weight:900;margin-right:6px}.billing-primary{width:100%;border:1.5px solid #f5a623;background:#f5a623;color:#1a1a2e;border-radius:999px;padding:13px 18px;font-weight:900;font-size:14px;cursor:pointer;box-shadow:0 8px 22px rgba(245,166,35,.25)}.billing-primary:disabled{opacity:.6;cursor:not-allowed}.billing-note{text-align:center;color:#6b7280;font-size:10.5px;margin-top:11px}.billing-auth{display:none;background:linear-gradient(135deg,#fff8ed,#fff);border:1px solid #f5c45b;border-radius:18px;padding:22px}.billing-auth.open{display:block}.billing-auth h3{font-size:22px;margin:0 0 5px;color:#1a1a2e;text-align:center}.billing-auth-copy{text-align:center;color:#6b7280;font-size:12px;margin-bottom:14px}.billing-auth input{width:100%;box-sizing:border-box;padding:12px 13px;border:1.5px solid #e5e7eb;border-radius:10px;margin-top:8px;outline:none}.billing-auth input:focus{border-color:#f5a623;box-shadow:0 0 0 3px rgba(245,166,35,.12)}.billing-auth-switch{display:grid;grid-template-columns:1fr 1fr;gap:7px;background:#f3f4f6;border-radius:12px;padding:5px;margin:12px 0}.billing-auth-switch button{border:0;background:transparent;border-radius:9px;padding:9px;cursor:pointer;font-weight:800;color:#6b7280}.billing-auth-switch button.active{background:#fff;color:#1a1a2e;box-shadow:0 2px 8px rgba(0,0,0,.07)}.billing-code{display:grid;grid-template-columns:1fr auto;gap:7px;margin:8px 0 12px}.billing-code input{margin-top:0;text-transform:uppercase}.billing-code button{border:1.5px solid #f5a623;background:#fff;border-radius:9px;padding:0 12px;font-weight:800;cursor:pointer}.billing-back{width:100%;border:0;background:none;padding:10px;color:#6b7280;cursor:pointer}.billing-status{display:none;margin-top:10px;padding:9px 11px;border-radius:9px;font-size:12px}.billing-status.show{display:block}.billing-status.info{background:#eff6ff;color:#1e40af}.billing-status.error{background:#fef2f2;border:1px solid #fecaca;color:#991b1b}.billing-status.success{background:#ecfdf5;border:1px solid #bbf7d0;color:#166534}.credit-pill{display:inline-flex;align-items:center;gap:5px;background:#fff8ed;border:1px solid #f3d594;border-radius:99px;padding:5px 9px;font-size:11px;font-weight:800;color:#7c5a13}.pro-price-label{display:flex;align-items:center;justify-content:center;gap:5px;color:#f5a623;font-size:10px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;margin-bottom:8px}.premium-crown{width:16px;height:16px;fill:#f5a623}.pro-status:empty{display:none!important}@media(max-width:620px){.billing-box{padding:22px 16px;border-radius:18px}.billing-head h2{font-size:25px}.billing-features{grid-template-columns:1fr}.billing-price strong{font-size:34px}.billing-credits{align-items:flex-start;flex-direction:column}.billing-save-tag{right:0}}
</style>'''

MODAL = r'''<div class="billing-modal" id="careerBillingModal" aria-hidden="true"><div class="billing-box"><button class="billing-close" id="billingClose" type="button" aria-label="Close">×</button><div class="billing-head"><svg class="billing-crown" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7.5 7.5 11 12 4l4.5 7L21 7.5 19.2 18H4.8L3 7.5Zm2.7 8.5h12.6l.7-4.1-2.9 2.2-4.1-6.3-4.1 6.3L5 11.9 5.7 16Z"/></svg><h2>Career Pro</h2><p>Choose the plan that fits you. Every paid plan includes 2,000 AI credits each month.</p></div><div id="billingPlans"><div class="billing-tabs"><button class="billing-plan" data-plan="monthly" type="button"><b>Monthly Billing</b></button><button class="billing-plan active" data-plan="yearly" type="button"><b>Yearly Billing</b><span class="billing-save-tag">SAVE 43%</span></button></div><div class="billing-plan-main"><div class="billing-price"><div><strong id="billingPrice">$4</strong> <span class="period">/ month</span></div><p id="billingLine">$48 USD billed annually</p><span class="billing-save" id="billingSave">Save $35.88 per year</span></div><div class="billing-credits"><div><b>2,000 AI credits / month</b><br><span>Credits refresh each month while Career Pro is active.</span></div><span id="billingValue">Best value</span></div><div class="billing-features"><div><span>✓</span><strong>Free ATS + CV extraction</strong> — 0 credits</div><div><span>✓</span><strong>AI Resume Optimizer</strong> — 100 credits</div><div><span>✓</span><strong>AI Cover Letter</strong> — 50 credits</div><div><span>✓</span><strong>Section Regeneration</strong> — 20 credits</div><div><span>✓</span><strong>AI PDF Summarizer</strong> — 25 credits</div><div><span>✓</span><strong>PDF & DOCX export</strong> — 0 credits</div></div><button class="billing-primary" id="billingContinue" type="button">Continue with Yearly</button><div class="billing-note">Your selected billing amount is shown before payment.</div></div></div><div class="billing-auth" id="billingAuth"><h3 id="billingAuthTitle">Sign in to continue</h3><p class="billing-auth-copy">Your Career Pro access stays linked to your EggyPDF account across devices.</p><div class="billing-auth-switch"><button type="button" class="active" data-auth="login">Sign in</button><button type="button" data-auth="signup">Create account</button></div><input id="billingEmail" type="email" autocomplete="email" placeholder="Email address"><input id="billingPassword" type="password" autocomplete="current-password" placeholder="Password (8+ characters)"><div class="billing-code"><input id="billingCreatorCode" placeholder="Creator Code (optional)"><button id="billingApplyCode" type="button">Apply</button></div><button class="billing-primary" id="billingAuthSubmit" type="button">Sign in & Continue</button><button type="button" class="billing-back" id="billingBack">← Back to plans</button></div><div class="billing-status" id="billingStatus"></div></div></div>'''

JS = r'''<script id="careerBillingScript">
(function(){
const BILLING_API='https://eggypdf-backend-1.onrender.com',ACCOUNT_KEY='eggypdf_account_session',BILLING_CHECKOUT_KEY='eggypdf_career_billing_checkout';let selectedPlan='yearly',authMode='login';
const q=id=>document.getElementById(id),session=()=>{try{return JSON.parse(localStorage.getItem(ACCOUNT_KEY)||'null')}catch(_){return null}},token=()=>session()?.access_token||'',headers=(json=true)=>{let h={};if(json)h['Content-Type']='application/json';if(token())h.Authorization='Bearer '+token();return h};
async function body(r){let t='';try{t=await r.text()}catch(_){}if(!t)return{};try{return JSON.parse(t)}catch(_){return{success:false,error:r.ok?'The server returned an unexpected response. Please try again.':'The service is temporarily unavailable. Please try again.'}}}
function status(msg,type='info'){let e=q('billingStatus');if(!e)return;if(!msg){e.textContent='';e.className='billing-status';return}e.textContent=msg;e.className='billing-status show '+type}function clearStatus(){status('')}
function setPlan(plan){selectedPlan=plan==='monthly'?'monthly':'yearly';document.querySelectorAll('.billing-plan').forEach(b=>b.classList.toggle('active',b.dataset.plan===selectedPlan));let yearly=selectedPlan==='yearly';q('billingPrice').textContent=yearly?'$4':'$6.99';q('billingLine').textContent=yearly?'$48 USD billed annually':'$6.99 USD billed monthly';q('billingSave').style.display=yearly?'inline-block':'none';q('billingValue').textContent=yearly?'Best value':'Monthly plan';q('billingContinue').textContent=yearly?'Continue with Yearly':'Continue with Monthly';clearStatus()}
async function refreshSession(){let s=session();if(!s?.refresh_token)return false;try{let r=await fetch(BILLING_API+'/api/account/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})}),d=await body(r);if(r.ok&&d.success&&d.session?.access_token){localStorage.setItem(ACCOUNT_KEY,JSON.stringify(d.session));return true}}catch(_){}localStorage.removeItem(ACCOUNT_KEY);return false}
async function accountState(retry=true){if(!token())return null;try{let r=await fetch(BILLING_API+'/api/billing/me',{headers:headers(false)});if(r.status===401&&retry&&await refreshSession())return accountState(false);let d=await body(r);if(r.status===401)localStorage.removeItem(ACCOUNT_KEY);return r.ok?d:null}catch(_){return null}}
async function openOffer(){clearStatus();let me=await accountState();if(me?.career_pro?.active){location.href='career-pro.html';return}let m=q('careerBillingModal');m.classList.add('open');m.setAttribute('aria-hidden','false');q('billingPlans').style.display='block';q('billingAuth').classList.remove('open');setPlan('yearly')}
window.openCareerProOffer=openOffer;
function closeOffer(){let m=q('careerBillingModal');m.classList.remove('open','show');m.setAttribute('aria-hidden','true');clearStatus()}
async function createCheckout(){let r=await fetch(BILLING_API+'/api/billing/checkout',{method:'POST',headers:headers(),body:JSON.stringify({plan:selectedPlan})}),d=await body(r);if(!r.ok||!d.success||!d.checkout_url||!d.session_id)throw Error(d.error||'Could not start checkout.');localStorage.setItem(BILLING_CHECKOUT_KEY,d.session_id);location.assign(d.checkout_url)}
async function authAndContinue(){let email=q('billingEmail').value.trim(),password=q('billingPassword').value,btn=q('billingAuthSubmit');if(!email||!password){status('Enter your email and password.','error');return}btn.disabled=true;status(authMode==='signup'?'Creating your account…':'Signing you in…','info');try{let r=await fetch(BILLING_API+'/api/account/'+(authMode==='signup'?'signup':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})}),d=await body(r);if(!r.ok||!d.success)throw Error(d.error||'Account request failed.');if(d.needs_email_confirmation){status('Check your email and confirm your EggyPDF account. Then come back and sign in to continue.','info');return}if(!d.session?.access_token)throw Error('No account session was returned.');localStorage.setItem(ACCOUNT_KEY,JSON.stringify(d.session));let code=q('billingCreatorCode').value.trim();if(code){let cr=await fetch(BILLING_API+'/api/billing/creator-code/redeem',{method:'POST',headers:headers(),body:JSON.stringify({code})}),cd=await body(cr);if(cr.ok&&cd.success){status('Creator Code applied. Career Pro is active.','success');setTimeout(()=>location.href='career-pro.html',450);return}if(!cr.ok)status(cd.error||'Creator Code could not be applied. Continuing to checkout.','info')}await createCheckout()}catch(e){status(e.message||'Could not continue. Please try again.','error')}finally{btn.disabled=false}}
document.querySelectorAll('.billing-plan').forEach(b=>b.addEventListener('click',()=>setPlan(b.dataset.plan)));q('billingClose').onclick=closeOffer;q('careerBillingModal').addEventListener('click',e=>{if(e.target===q('careerBillingModal'))closeOffer()});q('billingContinue').onclick=async()=>{let me=await accountState();if(me){try{await createCheckout()}catch(e){status(e.message||'Could not start checkout.','error')}return}q('billingPlans').style.display='none';q('billingAuth').classList.add('open');clearStatus()};q('billingBack').onclick=()=>{q('billingPlans').style.display='block';q('billingAuth').classList.remove('open');setPlan(selectedPlan)};document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;document.querySelectorAll('[data-auth]').forEach(x=>x.classList.toggle('active',x===b));q('billingAuthTitle').textContent=authMode==='signup'?'Create your EggyPDF account':'Sign in to continue';q('billingAuthSubmit').textContent=authMode==='signup'?'Create Account & Continue':'Sign in & Continue';q('billingPassword').autocomplete=authMode==='signup'?'new-password':'current-password';clearStatus()});q('billingAuthSubmit').onclick=authAndContinue;q('billingApplyCode').onclick=async()=>{if(!token()){status('Sign in or create your account first, then apply the Creator Code.','info');return}let code=q('billingCreatorCode').value.trim();if(!code){status('Enter a Creator Code.','error');return}try{let r=await fetch(BILLING_API+'/api/billing/creator-code/redeem',{method:'POST',headers:headers(),body:JSON.stringify({code})}),d=await body(r);if(!r.ok||!d.success)throw Error(d.error||'Creator Code could not be applied.');status('Creator Code applied. Career Pro is active.','success');setTimeout(()=>location.href='career-pro.html',450)}catch(e){status(e.message||'Creator Code could not be applied.','error')}};
})();
</script>'''

PRO_JS = r'''<script id="careerProAccountPatch">
(function(){const ACCOUNT_KEY='eggypdf_account_session',API='https://eggypdf-backend-1.onrender.com';let s=null;try{s=JSON.parse(localStorage.getItem(ACCOUNT_KEY)||'null')}catch(_){}let token=s?.access_token||'';if(!token)return;const authHeaders=(json=false)=>{let h={Authorization:'Bearer '+token};if(json)h['Content-Type']='application/json';return h};window.eggyAuthHeaders=authHeaders;async function safeJson(r){try{return await r.json()}catch(_){return{}}}async function accountGate(){try{let r=await fetch(API+'/api/billing/me',{headers:authHeaders()}),d=await safeJson(r);if(!r.ok||!d.career_pro?.active)throw Error(d.error||'Career Pro is not active on this account.');let gate=document.getElementById('gate'),workspace=document.getElementById('workspace');if(gate)gate.style.display='none';if(workspace)workspace.style.display='block';let credits=d.credits?.balance;if(credits!==undefined&&credits!==null){let pill=document.createElement('span');pill.className='credit-pill';pill.id='careerCreditPill';pill.textContent=Number(credits).toLocaleString()+' credits';let head=document.querySelector('.head');if(head)head.insertBefore(pill,head.querySelector('.back'))}}catch(e){let gs=document.getElementById('gateStatus');if(gs){gs.className='status error';gs.textContent='Sign in with an active Career Pro account to continue.'}}}window.addEventListener('DOMContentLoaded',accountGate);const nativeFetch=window.fetch.bind(window);window.fetch=function(input,init={}){let url=typeof input==='string'?input:(input&&input.url)||'';if(url.includes('/api/career/pro/')){let h=new Headers(init.headers||{});h.set('Authorization','Bearer '+token);if(!h.has('X-Idempotency-Key')&&['/optimize','/cover-letter','/regenerate-section','/pdf-summary','/tailor'].some(x=>url.includes(x)))h.set('X-Idempotency-Key',crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random());init={...init,headers:h}}return nativeFetch(input,init)};
})();
</script>'''


def patch_ats(path):
    p=Path(path); s=p.read_text()
    if 'careerBillingStyle' not in s:s=s.replace('</head>',STYLE+'</head>',1)
    if 'id="careerBillingModal"' not in s:s=s.replace('</body>',MODAL+'</body>',1)
    if 'id="careerBillingScript"' not in s:s=s.replace('</body>',JS+'</body>',1)

    # Route all Career Pro CTA buttons through the current subscription modal.
    s=s.replace("document.getElementById('unlockPro').addEventListener('click',e=>startCheckout(e.currentTarget));","document.getElementById('unlockPro').addEventListener('click',e=>openCareerProOffer());")
    s=s.replace("document.getElementById('unlockPro').addEventListener('click',()=>startCheckout());","document.getElementById('unlockPro').addEventListener('click',()=>openCareerProOffer());")
    s=s.replace("if(unlockProTop)unlockProTop.addEventListener('click',e=>startCheckout(e.currentTarget));","if(unlockProTop)unlockProTop.addEventListener('click',e=>openCareerProOffer());")
    s=s.replace('restoreCareerPro();','/* Career Pro V1 billing restoration handled by the current account/payment recovery layer. */')

    # Keep the polished Career Pro card presentation from the preferred package.
    s=re.sub(r'<div class="pro-price">.*?</div><button class="pro-btn" id="unlockPro" type="button">.*?</button><div class="pro-note">.*?</div>', '<div class="pro-price"><span class="pro-price-label"><svg class="premium-crown" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7.5 7.5 11 12 4l4.5 7L21 7.5 19.2 18H4.8L3 7.5Zm2.7 8.5h12.6l.7-4.1-2.9 2.2-4.1-6.3-4.1 6.3L5 11.9 5.7 16Z"/></svg> Premium</span>From $4 USD<small>$48 yearly · or $6.99 monthly · 2,000 AI credits/month</small></div><button class="pro-btn" id="unlockPro" type="button">View Career Pro Plans</button><div class="pro-note">Choose Yearly or Monthly. Yearly is selected by default and saves 43%.</div>', s, count=1, flags=re.S)

    # Never expose low-level browser/JSON errors in the public Career Pro card.
    old="function setProStatus(message,type='info'){const el=document.getElementById('proStatus');el.textContent=message;el.className='pro-status '+type}"
    new="function setProStatus(message,type='info'){const el=document.getElementById('proStatus');if(!el)return;if(type==='error'){el.textContent='';el.className='pro-status';return}el.textContent=message||'';el.className=message?'pro-status '+type:'pro-status'}"
    s=s.replace(old,new)
    p.write_text(s)


def patch_pro(path):
    p=Path(path); s=p.read_text()
    if 'careerBillingStyle' not in s:s=s.replace('</head>',STYLE+'</head>',1)
    if 'careerProAccountPatch' not in s:s=s.replace('</body>',PRO_JS+'</body>',1)
    p.write_text(s)


def validate(ats_path, pro_path):
    ats=Path(ats_path).read_text(); pro=Path(pro_path).read_text()
    assert 'id="careerBillingModal"' in ats
    assert 'Monthly Billing' in ats and 'Yearly Billing' in ats
    assert 'SAVE 43%' in ats and '$48 USD billed annually' in ats
    assert '$6.99 USD billed monthly' in ats and '2,000 AI credits / month' in ats
    assert 'Continue with Yearly' in ats and 'Continue with Monthly' in ats
    assert '/api/billing/checkout' in ats and '/api/billing/me' in ats
    assert '/api/account/' in ats and '/api/billing/creator-code/redeem' in ats
    assert 'View Career Pro Plans' in ats and 'From $4 USD' in ats
    assert "type==='error'" in ats
    assert 'Cancel anytime' not in ats
    assert 'Payments already made are non-refundable except where required by law.' not in ats
    assert 'careerProAccountPatch' in pro and '/api/billing/me' in pro and 'X-Idempotency-Key' in pro


if __name__=='__main__':
    import sys
    patch_ats(sys.argv[1]); patch_pro(sys.argv[2]); validate(sys.argv[1],sys.argv[2])
